from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    border = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The enclosed regions are the only areas of the background not reachable from an edge.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == border or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                component.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != border and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not touches_edge:
                for y, x in component:
                    out[y][x] = 4
    return out

